INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-suttlers-row', 'west', 'the-camp-tail', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-camp-tail', 'door', 'The Camp''s Tail', 'The last of the hut hollows, set further apart than the ranks behind them and not in any rank at all, as if the camp ran out of order before it ran out of ground. The turf over them is rough and tussocked. Beyond the last one the bank of the lines bends away west and stops pretending to face the walls.', 0, 0, 'out', 0, -3, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-camp-tail', 'east', 'the-suttlers-row', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-camp-tail', 'north', 'the-picket-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-camp-tail', 'west', 'the-camp-midden', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-picket-ground', 'door', 'The Picket Ground', 'A line of stake holes across the turf, still plain as a row of stitches, where the horses were tethered on the long ropes. The grass grows rank along the line and short between. A pair of wicker gabions left standing at the end of it have gone grey and rotten, and something has dug under one of them.', 0, 0, 'out', 0, -3, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-picket-ground', 'south', 'the-camp-tail', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-picket-ground', 'west', 'the-forage-cut', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-picket-ground', 'north', 'the-horse-pits', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-forage-cut', 'door', 'The Forage Cut', 'A broad strip of ground cut bare and never let grow back properly, where the camp scythed fodder for its horses for a season until there was nothing left to cut. The turf came back thin, in tussocks, with the chalk showing between. It runs west along the bank of the lines and gives out in rough grass.', 0, 0, 'out', 0, -4, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-forage-cut', 'east', 'the-picket-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-forage-cut', 'south', 'the-camp-midden', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-forage-cut', 'north', 'the-camp-graves', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-forage-cut', 'west', 'the-plague-tents', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-camp-midden', 'door', 'The Camp Midden', 'A long low mound grassed over at the back of the camp, where everything the army threw away went for a season. Bone and broken pot and black ash come up wherever the turf is torn, and the turf is torn all over it, dug at by things that know what a midden is.', 0, 0, 'out', 0, -4, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-camp-midden', 'north', 'the-forage-cut', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-camp-midden', 'east', 'the-camp-tail', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-camp-midden', 'west', 'the-deserters-ditch', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-horse-pits', 'door', 'The Horse Pits', 'Two long hollows side by side in the grass, slumped deeper than the hut hollows and longer than any of them, where the horses that died in the lines were dragged and covered. The ground sounds different underfoot. There are holes dug into both of them at the ends, old and new.', 0, 0, 'out', 0, -3, 2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-horse-pits', 'south', 'the-picket-ground', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-horse-pits', 'west', 'the-camp-graves', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-camp-graves', 'door', 'The Camp Graves', 'The army''s own dead, behind its own lines: rows of low turf mounds, close-set and short, with a few round stone shot laid at the heads of them for want of anything better to mark them with. The rows are straight. Some of the mounds have been opened from the side, low down, and not by a spade.', 0, 0, 'out', 0, -4, 2);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-camp-graves', 'south', 'the-forage-cut', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-camp-graves', 'east', 'the-horse-pits', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-deserters-ditch', 'door', 'The Deserters'' Ditch', 'A short deep ditch cut across the end of the bank, grassed now, where the lines were closed off at the back to keep the army in. The ditch side is steep and the bottom wet. A stake still stands at one end of it with the iron of a collar rusted round its foot.', 0, 0, 'out', 0, -5, 4);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deserters-ditch', 'east', 'the-camp-midden', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-deserters-ditch', 'north', 'the-plague-tents', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-plague-tents', 'door', 'The Plague Tents', 'A square of hut hollows set apart from all the others, a long throw from the camp, with a ditch round them and only one way across it. Whatever went into these did not come back out into the camp. The hollows are deeper than the rest, and the grass in them is greener than it has any right to be.', 0, 0, 'out', 0, -5, 3);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plague-tents', 'south', 'the-deserters-ditch', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-plague-tents', 'east', 'the-forage-cut', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-village-smithy', 'north', 'the-toft-ends', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-toft-ends', 'door', 'The Toft Ends', 'The backs of the house-plots behind the smithy, each one marked off by a line of low stone footing, each with its own black stump of a post where a fence or a pen stood. The plots run back from the lane in narrow strips. Ash still lies in the corners of them where the wind cannot get it out.', 0, 0, 'out', 0, -4, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-toft-ends', 'south', 'the-village-smithy', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-toft-ends', 'north', 'the-back-lane', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-toft-ends', 'west', 'the-stray-pound', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-back-lane', 'door', 'The Back Lane', 'A narrow way behind the houses, between low stone footings on either side, where the carts came round to the yards. The ruts are filled with grass now. Charred posts stand along it at the yard gates, and every one of the gates is gone.', 0, 0, 'out', 0, -4, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-lane', 'south', 'the-toft-ends', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-lane', 'west', 'the-crofts', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-lane', 'east', 'the-goose-green', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-goose-green', 'door', 'The Goose Green', 'A little triangle of open ground at the lane''s end, cropped short, with a stone trough at one side of it gone green and a scatter of burned timbers along the other. The village kept its geese here. The grass is still cropped short, and the droppings in it are not a goose''s.', 0, 0, 'out', 0, -3, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-goose-green', 'west', 'the-back-lane', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-stray-pound', 'door', 'The Stray Pound', 'A square of low stone walling with a gap for a gate, where strays were penned until somebody paid to have them back. The walling has held where the houses did not. There are bones in the corner of it, and they are not old.', 0, 0, 'out', 0, -5, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stray-pound', 'east', 'the-toft-ends', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stray-pound', 'north', 'the-crofts', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-stray-pound', 'west', 'the-back-pond', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-crofts', 'door', 'The Crofts', 'The garden plots behind the last houses, laid out in low stone-kerbed beds, all of them gone to dock and nettle. A well stands among them with its sweep-arm fallen across the beds. Somebody grew the village''s beans here, and the beds are still exactly as straight as they made them.', 0, 0, 'out', 0, -5, 5);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crofts', 'east', 'the-back-lane', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-crofts', 'south', 'the-stray-pound', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-back-pond', 'door', 'The Back Pond', 'A round pond behind the pound, stone-edged on one side, where the village watered its beasts. The water is low and black and still, and the ground round it is trodden to mud by everything that comes to drink. Burned posts lean over it from the plot behind.', 0, 0, 'out', 0, -6, 6);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-back-pond', 'east', 'the-stray-pound', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-cider-house', 'south', 'the-windfall-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-culver-house', 'south', 'the-field-gate', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-windfall-bank', 'door', 'The Windfall Bank', 'A bank of bare earth below the orchard where the fruit rolled and rotted every autumn and nobody came to pick it up. The thorn has come up along the top of it in a dead hedge. The ground at its foot is churned and scraped and printed all over.', 0, 0, 'out', 0, -2, 14);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-windfall-bank', 'north', 'the-cider-house', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-windfall-bank', 'east', 'the-field-gate', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-windfall-bank', 'south', 'the-waste-fields', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-windfall-bank', 'west', 'the-dead-hedge', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-field-gate', 'door', 'The Field Gate', 'A gap in the old field hedge, which is dead thorn now, grey and leafless and higher than a man. The gap was a gate once. The track through it is worn down to bare earth by things that go the same way every night.', 0, 0, 'out', 0, -1, 14);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-field-gate', 'north', 'the-culver-house', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-field-gate', 'west', 'the-windfall-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-field-gate', 'south', 'the-field-bank', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-dead-hedge', 'door', 'The Dead Hedge', 'The field''s old boundary, a hedge laid by hand long ago and let go, grown out into a wall of dead thorn with bare earth at its foot. Bones have been dragged into the bottom of it and left where the thorn keeps everything else off them.', 0, 0, 'out', 0, -3, 14);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-hedge', 'east', 'the-windfall-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-dead-hedge', 'south', 'the-old-plough', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-waste-fields', 'door', 'The Waste Fields', 'What was ploughland, south of the holding: wide, bare and lumpy, the ridges of the old furrows still showing under thin grass and bare earth. Nothing has been sown here in two hundred years. The thorn has come in from every hedge and stands about the field in dead clumps.', 0, 0, 'out', 0, -2, 15);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-waste-fields', 'north', 'the-windfall-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-waste-fields', 'east', 'the-field-bank', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-waste-fields', 'west', 'the-old-plough', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-field-bank', 'door', 'The Field Bank', 'A low earth bank across the bottom of the fields, where the plough turned. A dead tree stands alone on it, bare and split. From the top of the bank the gibbet hill shows over the thorn to the east, and the ground in front of it is open the whole way.', 0, 0, 'out', 0, -1, 15);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-field-bank', 'north', 'the-field-gate', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-field-bank', 'west', 'the-waste-fields', NULL);
INSERT INTO rooms (id, zone, name, description, is_entry, is_safe, region, is_spawn, map_x, map_y) VALUES
  ('the-old-plough', 'door', 'The Old Plough', 'A corner of the fields where the plough itself was left, an iron share and a rotted beam sunk into bare earth at the end of a furrow that was never finished. The furrow still runs straight from it across the field. Something lies up against the share by day; the earth there is pressed flat.', 0, 0, 'out', 0, -3, 15);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-plough', 'north', 'the-dead-hedge', NULL);
INSERT INTO exits (room_id, dir, to_room, key_item) VALUES ('the-old-plough', 'east', 'the-waste-fields', NULL);
